#!/usr/bin/env bash
# =============================================================================
# setup_squad_hq.sh — one-file installer for the Squad HQ (RDS-style) kit
#
# What it does, in order:
#   1. Checks your OS (macOS, Linux, or WSL on Windows).
#   2. (Optional, --install-tools) Installs git, Node.js, gh, uv, Backlog.md, and Claude Code.
#   3. Backs up your current CLAUDE.md, PROGRESS.md, .gitignore, and .claude/commands.
#   4. Renames your old PROGRESS.md to PROGRESS.pre-reset.md (clean start).
#   5. Unpacks the kit (embedded at the end of this file) into your workspace.
#   6. Runs tools/bootstrap_tracker.sh: creates the tracker, sprints S01–S02, and 26 Stage 0 tickets.
#   7. Verifies everything and prints your next step.
#
# It never deletes your files, never commits for you, and never touches curriculum/ or .claude/skills/.
#
# Usage:
#   bash setup_squad_hq.sh                         # workspace = current folder
#   bash setup_squad_hq.sh --workspace ~/squad-hq  # pick the folder
#   bash setup_squad_hq.sh --install-tools         # also install the tools
#   bash setup_squad_hq.sh --skip-bootstrap        # do not create tickets yet
#   bash setup_squad_hq.sh --yes                   # no confirmation prompts
#   bash setup_squad_hq.sh --dry-run               # show what would happen, change nothing
# =============================================================================
set -euo pipefail

WS="$(pwd)"
INSTALL_TOOLS=0
SKIP_BOOTSTRAP=0
ASSUME_YES=0
DRY_RUN=0
SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"

while [ $# -gt 0 ]; do
  case "$1" in
    --workspace) WS="$2"; shift 2 ;;
    --install-tools) INSTALL_TOOLS=1; shift ;;
    --skip-bootstrap) SKIP_BOOTSTRAP=1; shift ;;
    --yes|-y) ASSUME_YES=1; shift ;;
    --dry-run) DRY_RUN=1; shift ;;
    -h|--help) sed -n '2,24p' "$SELF"; exit 0 ;;
    *) echo "Unknown option: $1 (use --help)"; exit 2 ;;
  esac
done

# ---------- output helpers ----------
if [ -t 1 ]; then B=$'\033[1m'; G=$'\033[32m'; Y=$'\033[33m'; R=$'\033[31m'; N=$'\033[0m'; else B=""; G=""; Y=""; R=""; N=""; fi
step() { echo; echo "${B}==> $*${N}"; }
ok()   { echo "  ${G}✔${N} $*"; }
warn() { echo "  ${Y}!${N} $*"; }
die()  { echo "  ${R}✘ $*${N}"; exit 1; }
run()  { if [ "$DRY_RUN" = 1 ]; then echo "  [dry-run] $*"; else eval "$@"; fi; }
have() { command -v "$1" >/dev/null 2>&1; }
confirm() {
  [ "$ASSUME_YES" = 1 ] && return 0
  [ "$DRY_RUN" = 1 ] && return 0
  read -r -p "  $1 [y/N] " a; [[ "$a" =~ ^[Yy]$ ]]
}
b64d() { base64 --decode 2>/dev/null || base64 -D; }

# ---------- 1. OS check ----------
step "1/7 Checking your system"
OS="$(uname -s)"
case "$OS" in
  Darwin) PLATFORM=mac; ok "macOS $(sw_vers -productVersion 2>/dev/null || true)" ;;
  Linux)  PLATFORM=linux
          if grep -qi microsoft /proc/version 2>/dev/null; then ok "Linux on WSL"; else ok "Linux"; fi ;;
  *) die "Unsupported system: $OS. On Windows, install WSL (Ubuntu) and run this inside it." ;;
esac
have tar || die "tar is required."
have base64 || die "base64 is required."

WS="${WS/#\~/$HOME}"
if [ ! -d "$WS" ]; then
  confirm "Workspace $WS does not exist. Create it?" || die "Stopped."
  run "mkdir -p \"$WS\""
fi
WS="$(cd "$WS" 2>/dev/null && pwd || echo "$WS")"
ok "Workspace: $WS"
[ -f "$WS/CLAUDE.md" ] && ok "Found existing CLAUDE.md (it will be backed up)" || warn "No CLAUDE.md yet — a fresh workspace. That is fine."
[ -d "$WS/curriculum" ] && ok "Found curriculum/" || warn "No curriculum/ folder. Copy roadmap.html and resource-library.xlsx into $WS/curriculum/ (CLAUDE.md uses them)."
[ -f "$WS/.claude/skills/explain/SKILL.md" ] && ok "Found the explain skill" || warn "No .claude/skills/explain/SKILL.md. CLAUDE.md requires it: copy your explain skill folder there."

# ---------- 2. Tools ----------
step "2/7 Tools"
add_path_line() {   # add a PATH line to the shell profile once
  local line="$1" rc
  case "${SHELL:-}" in */zsh) rc="$HOME/.zshrc" ;; *) rc="$HOME/.bashrc" ;; esac
  grep -qsF "$line" "$rc" || { run "echo '$line' >> \"$rc\""; warn "Added to $rc: $line (open a new terminal later)"; }
}
node_ok() { have node && [ "$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)" -ge 18 ]; }

if [ "$INSTALL_TOOLS" = 1 ]; then
  confirm "Install missing tools (git, Node.js 18+, gh, uv, Backlog.md, Claude Code)?" || die "Stopped. Re-run without --install-tools to skip installs."
  if [ "$PLATFORM" = mac ]; then
    if ! have brew; then
      warn "Homebrew (the macOS package manager) is missing. Installing it; it may ask for your password."
      run '/bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"'
      [ -x /opt/homebrew/bin/brew ] && eval "$(/opt/homebrew/bin/brew shellenv)" && add_path_line 'eval "$(/opt/homebrew/bin/brew shellenv)"'
    fi
    for pkg in git node gh uv; do
      if have "$pkg" && { [ "$pkg" != node ] || node_ok; }; then ok "$pkg already installed"; else run "brew install $pkg"; fi
    done
  else
    have apt-get || die "This script installs tools with apt (Debian/Ubuntu/WSL). On other Linux, install git, Node.js 18+, gh, and uv yourself, then re-run without --install-tools."
    run "sudo apt-get update -y"
    run "sudo apt-get install -y git curl unzip ca-certificates"
    if node_ok; then ok "Node.js $(node --version) already installed"; else
      run "sudo apt-get install -y nodejs npm"
      node_ok || warn "Your apt Node.js is older than 18. Install a newer one (for example with nvm: https://github.com/nvm-sh/nvm), then re-run."
    fi
    if have gh; then ok "gh already installed"; else run "sudo apt-get install -y gh" || warn "gh not in apt here. See https://cli.github.com for install steps."; fi
    if have uv; then ok "uv already installed"; else
      run "curl -LsSf https://astral.sh/uv/install.sh | sh"
      export PATH="$HOME/.local/bin:$PATH"; add_path_line 'export PATH="$HOME/.local/bin:$PATH"'
    fi
  fi
  # Global npm installs without sudo: use a user-owned prefix if the default is not writable.
  if have npm; then
    NPM_PREFIX="$(npm config get prefix 2>/dev/null || echo /usr/local)"
    if [ ! -w "$NPM_PREFIX/lib" ] 2>/dev/null && [ ! -w "$NPM_PREFIX" ]; then
      run "mkdir -p \"$HOME/.npm-global\" && npm config set prefix \"$HOME/.npm-global\""
      export PATH="$HOME/.npm-global/bin:$PATH"; add_path_line 'export PATH="$HOME/.npm-global/bin:$PATH"'
    fi
    if have backlog; then ok "Backlog.md already installed ($(backlog --version))"; else run "npm install -g backlog.md"; fi
  fi
  if have claude; then ok "Claude Code already installed"; else
    run "curl -fsSL https://claude.ai/install.sh | bash"   # official native installer
    export PATH="$HOME/.local/bin:$PATH"; add_path_line 'export PATH="$HOME/.local/bin:$PATH"'
  fi
fi

MISSING=0
for t in git node backlog claude; do
  if have "$t"; then ok "$t: $("$t" --version 2>/dev/null | head -1)"; else warn "$t: not found"; MISSING=1; fi
done
for t in gh uv; do have "$t" && ok "$t: $("$t" --version 2>/dev/null | head -1)" || warn "$t: not found (needed by TKT-003 / TKT-004; the mentor can teach the install then)"; done
node_ok || warn "Node.js 18+ is required by Backlog.md."
if [ "$MISSING" = 1 ]; then
  warn "Some required tools are missing. Re-run with --install-tools, or install them yourself."
  [ "$SKIP_BOOTSTRAP" = 0 ] && ! have backlog && { warn "Backlog.md is missing, so ticket creation will be skipped."; SKIP_BOOTSTRAP=1; }
fi

# ---------- 3. Backups ----------
step "3/7 Backing up your current files"
TS="$(date +%Y%m%d-%H%M%S)"
BK="$WS/.pre-kit-backup-$TS"
run "mkdir -p \"$BK\""
for f in CLAUDE.md PROGRESS.md .gitignore README.md; do
  [ -e "$WS/$f" ] && { run "cp -p \"$WS/$f\" \"$BK/\""; ok "Backed up $f"; }
done
[ -d "$WS/.claude/commands" ] && { run "mkdir -p \"$BK/.claude\" && cp -Rp \"$WS/.claude/commands\" \"$BK/.claude/\""; ok "Backed up .claude/commands"; }
ok "Backup folder: $BK"

# ---------- 4. Clean start ----------
step "4/7 Clean start"
ALREADY_SETUP=0; [ -d "$WS/backlog/tasks" ] && [ -n "$(ls -A "$WS/backlog/tasks" 2>/dev/null)" ] && ALREADY_SETUP=1
if [ "$ALREADY_SETUP" = 1 ]; then
  ok "Kit already set up here (tickets exist): progress left untouched"
elif [ -f "$WS/PROGRESS.md" ] && ! grep -q "not started" "$WS/PROGRESS.md"; then
  if [ -e "$WS/PROGRESS.pre-reset.md" ]; then warn "PROGRESS.pre-reset.md already exists; leaving it as is."
  else run "mv \"$WS/PROGRESS.md\" \"$WS/PROGRESS.pre-reset.md\""; ok "Old PROGRESS.md → PROGRESS.pre-reset.md (kept, not used for planning)"; fi
else
  ok "No old progress to archive"
fi
warn "Concept Log rows in curriculum/resource-library.xlsx are marked 'pre-reset' by the mentor in session 1 (never deleted)."

# ---------- 5. Unpack the kit ----------
step "5/7 Installing the kit files"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
sed -n '/^__KIT_PAYLOAD__$/,$p' "$SELF" | tail -n +2 | b64d | tar -xz -C "$TMP" || die "Could not unpack the embedded kit."
K="$TMP/rds-squad-kit"
[ -f "$K/CLAUDE.md" ] || die "Kit payload is damaged."

copy() { # copy kit path → workspace path
  local src="$K/$1" dst="$WS/${2:-$1}"
  run "mkdir -p \"$(dirname "$dst")\""
  if [ -d "$src" ]; then run "cp -R \"$src/.\" \"$dst/\""; else run "cp \"$src\" \"$dst\""; fi
  ok "${2:-$1}"
}
copy CLAUDE.md
if [ -f "$WS/PROGRESS.md" ]; then ok "PROGRESS.md kept (exists)"; else copy PROGRESS.md; fi
copy README.md SQUAD_HQ_README.md
copy docs/operating-model
copy .mentor
copy tools/bootstrap_tracker.sh
copy .claude/commands
copy .github/pull_request_template.md
if [ -d "$WS/backlog/tasks" ]; then warn "backlog/ already has tickets: config left unchanged"; else copy backlog/config.yml; fi
# Merge .gitignore: add kit lines that are missing, keep yours.
if [ -f "$WS/.gitignore" ]; then
  while IFS= read -r line; do
    [ -z "$line" ] && continue
    grep -qxF "$line" "$WS/.gitignore" || run "printf '%s\n' \"$line\" >> \"$WS/.gitignore\""
  done < "$K/.gitignore"
  ok ".gitignore (merged)"
else
  copy .gitignore
fi
grep -qxF ".pre-kit-backup-*/" "$WS/.gitignore" 2>/dev/null || run "printf '%s\\n' '.pre-kit-backup-*/' >> \"$WS/.gitignore\""
run "chmod +x \"$WS/tools/bootstrap_tracker.sh\""
run "mkdir -p \"$WS/projects\" \"$WS/docs/explainers\" \"$WS/tools/mocks\" \"$WS/tools/chaos\" \"$WS/tools/legacy\" \"$WS/reviews\" \"$WS/.mentor/review-keys\""
ok "Folders: projects/, docs/explainers/, tools/{mocks,chaos,legacy}/, reviews/"

# ---------- 6. Tracker ----------
step "6/7 Tracker and Stage 0 tickets"
if [ "$SKIP_BOOTSTRAP" = 1 ]; then
  warn "Skipped. Later, from $WS run: bash tools/bootstrap_tracker.sh"
elif [ -d "$WS/backlog/tasks" ] && [ -n "$(ls -A "$WS/backlog/tasks" 2>/dev/null)" ]; then
  warn "Tickets already exist in backlog/tasks. Not seeding again."
else
  if [ "$DRY_RUN" = 1 ]; then echo "  [dry-run] (cd \"$WS\" && bash tools/bootstrap_tracker.sh)"
  else
    (cd "$WS" && git config --global init.defaultBranch >/dev/null 2>&1 || git config --global init.defaultBranch main
     bash tools/bootstrap_tracker.sh) > "$BK/bootstrap.log" 2>&1 || { tail -20 "$BK/bootstrap.log"; die "Bootstrap failed. Full log: $BK/bootstrap.log"; }
    ok "$(grep '^Seeded' "$BK/bootstrap.log" || echo 'Tickets created')"
    ok "Log: $BK/bootstrap.log"
  fi
fi

# ---------- 7. Verify ----------
step "7/7 Verifying"
if [ "$DRY_RUN" = 1 ]; then ok "Dry run: nothing was changed."; else
  for f in CLAUDE.md PROGRESS.md docs/operating-model/RDS_MODEL.md docs/operating-model/TICKET_CATALOG.md docs/operating-model/TICKET_TEMPLATES.md docs/operating-model/COVERAGE_MAP.md docs/operating-model/FLEET.md .claude/commands/standup.md tools/bootstrap_tracker.sh; do
    [ -f "$WS/$f" ] && ok "$f" || warn "missing: $f"
  done
  grep -q "@docs/operating-model/RDS_MODEL.md" "$WS/CLAUDE.md" && ok "CLAUDE.md imports the RDS model" || warn "CLAUDE.md import line not found"
  if have backlog && [ -d "$WS/backlog/tasks" ]; then
    (cd "$WS" && backlog task list -s "In Progress,Ready" --plain 2>/dev/null | sed 's/^/  /')
  fi
fi

cat <<EOF

${B}Done. Your next steps:${N}
  1. Open a NEW terminal window (so PATH changes apply).
  2. cd "$WS"
  3. claude            # first time: log in with your Claude account (a paid plan is needed for Claude Code)
  4. Type this as your first message:
       Start the clean start: RDS_MODEL.md section 16. The setup script already installed the tools and created the tickets, so treat TKT-001 as "learn what was installed": teach me the terminal and each tool from zero, then check TKT-001's acceptance criteria.
  5. Daily: /standup → /next → build → /submit TKT-xxx → /ship TKT-xxx

  Web board:   backlog browser   (http://127.0.0.1:6420)
  Backups:     $BK
  Do NOT open: .mentor/  (incident causes and review answer keys)
  Not committed yet: TKT-002 is where you make the first commit yourself.
EOF
exit 0
__KIT_PAYLOAD__
H4sIAAAAAAAAA+xcW3PbyHL2s37FRJuqUHsIiqRuCeV4Dy3RtrKWpZXodbZcLnEIDEkcARjsDCCK
W3nYp/yAJE95y0t+2P6SfN0z4EWSrbPxWptzIpTLIgHMrbunv74NTWQD+2Mpo+AyLjaffJGriWtv
